(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {mail:'M4 5h16v14H4z M4 6l8 7 8-7', plane:'M22 2L9 15 M22 2l-7 20-6-7-7-6z', arrow:'M5 12h14 M13 6l6 6-6 6', plus:'M12 5v14 M5 12h14', check:'M5 12l4 4L19 6', copy:'M9 9h11v12H9z M15 9V3H3v12h6', box:'M4 5h16v14H4z M4 13h5l2 3h2l2-3h5', clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2', back:'M19 12H5 M11 6l-6 6 6 6', close:'M6 6l12 12 M6 18L18 6', trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7', grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z'};
  const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.mail}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  const brand = '<a class="brand" href="#/emails"><img src="../public/icon.png" alt=""/>Paperplane</a>';
  const button = (label, href, cls = '') => `<a class="button ${cls}" href="#${href}">${label}</a>`;
  function field(label,name,placeholder='',type='text',value='',extra='') {
    if(name==='name')extra=extra.replace('maxlength="30"','minlength="2" maxlength="8"');
    if(type==='email')extra+=' maxlength="254"';
    const input=`<input id="${name}" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" aria-describedby="${name}-error${type==='password'&&name==='password'?' password-checklist':''}" ${extra}/>`;
    return `<div class="field"><label for="${name}">${label}</label>${type==='password'?`<div class="password-wrap">${input}<button type="button" class="password-toggle" data-action="toggle-password" data-target="${name}" aria-label="${label} 표시" aria-pressed="false">보기</button></div>`:input}<p class="field-error" id="${name}-error" aria-live="polite"></p>${type==='password'&&name==='password'?'<div class="password-checklist" id="password-checklist"><span data-password-length>8자 이상</span><span data-password-special>특수문자 포함</span></div>':''}</div>`;
  }
  const pill = (label, cls = '') => `<span class="pill ${cls}">${label}</span>`;
  const initial = () => ({name:'지민', aliases:[{id:1,name:'shopping',rules:[{id:11,destination:'hello@example.com',conditions:[]}]},{id:2,name:'studio',rules:[{id:21,destination:'work@example.com',conditions:[{field:'subject',op:'contains',value:'프로젝트'}]}]},{id:3,name:'newsletter',rules:[]}],destinations:['hello@example.com','work@example.com']});
  let state = initial(), scenario = 'normal', failNext = false, authEmail = 'hello@example.com', codeSent = false, timerStart = 0, draft = null, dirty = false, nextId = 100;
  let route = '', toastTimer, verifyAttempts = 0, returnToRule = '';
  const app = $('#app'), dialog = $('#dialog');
  const hasSpecial = value => /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(value);
  function validateField(input) {
    if(!input.name||input.disabled)return;
    const message=document.getElementById(`${input.name}-error`);if(!message)return;
    let error='';
    if(input.validity.valueMissing)error='이 항목을 입력해 주세요.';
    else if(input.validity.typeMismatch)error='이메일 주소를 확인해 주세요.';
    else if(input.validity.tooShort)error=`${input.minLength}자 이상 입력해 주세요.`;
    else if(input.validity.patternMismatch)error=input.name==='code'?'6자리 숫자를 입력해 주세요.':'입력 형식을 확인해 주세요.';
    if(input.name==='password'&&input.value&&!hasSpecial(input.value))error='특수문자를 하나 이상 포함해 주세요.';
    if(input.name==='confirm'&&input.value.trim()!==$('#password')?.value.trim())error='비밀번호가 서로 달라요.';
    message.textContent=error;input.setAttribute('aria-invalid',String(!!error));
  }
  document.addEventListener('invalid',e=>validateField(e.target),true);
  document.addEventListener('blur',e=>{if(e.target.matches('input'))validateField(e.target);},true);
  document.addEventListener('input',e=>{
    if(e.target.id==='password'){
      $('[data-password-length]')?.classList.toggle('valid',e.target.value.length>=8);
      $('[data-password-special]')?.classList.toggle('valid',hasSpecial(e.target.value));
    }
    if(e.target.getAttribute('aria-invalid')==='true')validateField(e.target);
  });
  document.addEventListener('click',e=>{
    const link=e.target.closest('a[href^="#/"]');if(!link)return;
    if(route.startsWith('/rule/')&&link.hash==='#/destinations/new'){returnToRule=route;return;}
    if(dirty&&route.startsWith('/rule/')&&!link.dataset.action&&link.hash!==`#${route}`){
      e.preventDefault();
      const target=link.hash;
      modal('작성 중인 설정을 나갈까요?','<p>저장하지 않은 변경사항이 있어요. 나가면 이 초안은 삭제됩니다.</p>','<button class="button secondary" data-action="close">계속 편집</button><button class="button" id="discard-draft">저장하지 않고 나가기</button>');
      $('#discard-draft').onclick=()=>{dirty=false;draft=null;returnToRule='';dialog.close();location.hash=target;};
    }
  },true);
  const address = a => `${a.name}@paperplane.example`;
  const aliasBy = id => state.aliases.find(a => a.id === Number(id));
  const navigation = [['/emails','mail','내 이메일'],['/destinations','box','받는 메일함'],['/deliveries','clock','전달 기록']];
  const screens = [['서비스 소개','/'],['로그인','/login'],['이메일 가입','/signup'],['가입 코드 확인','/signup/verify'],['가입 정보','/signup/profile'],['소셜 인증 결과','/auth/callback'],['소셜 가입','/signup/social'],['비밀번호 복구','/password/reset'],['새 비밀번호','/password/reset/new'],['내 이메일','/emails'],['주소 만들기','/emails/new'],['주소 전달 설정','/email/1'],['전달 조건 편집','/rule/1/new'],['받는 메일함','/destinations'],['메일함 인증','/destinations/new'],['전달 기록','/deliveries'],['계정 설정','/settings'],['없는 페이지','/404'],['세션 만료','/session'],['첫 설정 완료','/success']];
  function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 3000); }
  function modal(title, body, actions = '') { dialog.className = ''; dialog.innerHTML = `<div class="row between"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="닫기">${icon('close')}</button></div>${body}${actions ? `<div class="dialog-actions">${actions}</div>` : ''}`; dialog.showModal(); $('.dialog-actions [data-action="close"]',dialog)?.focus(); }
  function heading(title, sub, action = '') { return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`; }
  function back(href = '/emails', label = '내 이메일') { return `<a class="back-link" href="#${href}">${icon('back')}${label}</a>`; }
  function empty(title, text, action = '') { return `<div class="empty"><span class="empty-icon">${icon('plane')}</span><h2>${title}</h2><p>${text}</p>${action}</div>`; }
  function formFoot(label = '저장하기', cancel = '/emails') { return `<p class="error" role="alert" data-error></p><div class="form-actions">${button('취소',cancel,'secondary')}<button class="button" type="submit">${label}${icon('arrow')}</button></div>`; }
  function demoBar() { return '<div class="demo-top"><span>디자인 미리보기 · 모든 데이터는 예시입니다</span><button data-action="gallery">화면 둘러보기 ↗</button></div>'; }
  function shell(content, title = '내 이메일', editor = false) {
    const nav = navigation.map(([url,ic,label]) => `<a href="#${url}" class="${route.startsWith(url) || (url === '/emails' && /^\/(email|rule)\//.test(route)) ? 'active' : ''}">${icon(ic)}<span>${label}</span>${url === '/emails' ? `<b class="nav-count">${state.aliases.length}</b>` : ''}</a>`).join('');
    return `<aside class="sidebar">${brand}<div class="nav-caption">WORKSPACE</div><nav class="nav" aria-label="주 메뉴">${nav}</nav><div class="side-bottom"><div class="side-note">조금 더 가벼운 메일 생활.<br/><span>필요한 곳에, 필요한 메일만.</span>${icon('plane')}</div><a href="#/settings" class="side-user"><span class="avatar">${esc(state.name.slice(0,1))}</span><span><strong>${esc(state.name)}</strong><small>개인 계정</small></span>${icon('settings')}</a></div></aside><header class="mobilebar">${brand}<button class="icon-button nav-gallery" data-action="gallery" aria-label="화면 둘러보기">${icon('grid')}</button><a class="avatar" href="#/settings" aria-label="계정 설정">${esc(state.name.slice(0,1))}</a></header><div class="shell"><header class="topbar"><div class="breadcrumb">워크스페이스 <span>/</span> <strong>${title}</strong></div><div class="row"><span class="preview-tag">디자인 미리보기</span><button class="text-button" data-action="gallery">화면 둘러보기 ${icon('grid')}</button><a class="avatar topbar-account" href="#/settings" aria-label="계정 설정">${esc(state.name.slice(0,1))}</a></div></header><main id="main" class="content ${editor ? 'editor-content' : ''}">${content}<footer class="app-footer">Paperplane <span>·</span> 필요한 곳에, 필요한 메일만.</footer></main></div>${editor ? '' : `<nav class="mobile-nav" aria-label="모바일 주 메뉴">${nav}</nav>`}`;
  }
  function specialState() {
    if (scenario === 'loading') return '<div class="loading-center" role="status"><span class="spinner"></span><p>불러오는 중입니다</p><div class="skeleton"></div><div class="skeleton"></div></div>';
    if (scenario === 'error') return empty('잠시 연결이 끊겼어요','입력한 내용은 그대로예요. 잠시 후 다시 시도해 주세요.','<button class="button secondary" data-action="retry">다시 시도</button>');
    return '';
  }
  function emails() {
    const rows = (scenario === 'empty' ? [] : state.aliases).map(a => `<div class="email-row"><div class="address-cell"><span class="icon-tile ${a.id === 2 ? 'lavender' : 'mint'}">${icon('mail')}</span><div><a class="address-title" href="#/email/${a.id}">${esc(a.name)}<span class="domain">@paperplane.example</span></a><div class="email-meta">개인 이메일 주소</div></div></div><div class="route-cell">${a.rules.length ? `<strong>${esc(a.rules[0].destination)}</strong><p>${a.rules[0].conditions.length ? '조건에 맞는 메일' : '모든 메일'}${a.rules.length > 1 ? ` 외 ${a.rules.length-1}개 규칙` : ''}</p>` : '<strong class="muted">받는 메일함을 연결해 주세요</strong><p>아직 전달 규칙이 없어요</p>'}</div><div class="status-cell">${pill(a.rules.length ? '설정 완료' : '설정 필요',a.rules.length ? '' : 'amber')}</div><div class="row-actions"><button class="icon-button" aria-label="${esc(a.name)} 주소 복사" data-action="copy" data-value="${address(a)}">${icon('copy')}</button><a class="icon-button" href="#/email/${a.id}" aria-label="${esc(a.name)} 전달 설정">${icon('arrow')}</a></div></div>`).join('');
    return shell(heading(`내 이메일 <span class="count">${scenario === 'empty' ? 0 : state.aliases.length}</span>`,'하나의 메일함으로, 나만의 주소를 자유롭게.',button(`${icon('plus')} 주소 만들기`,'/emails/new')) + (specialState() || `<section class="route-banner"><span class="icon-tile">${icon('plane')}</span><div><h3>내 주소는 가볍게. 메일은 한곳으로.</h3><p>서비스마다 다른 주소를 쓰고, 익숙한 메일함에서 받아보세요.</p></div><div class="mini-route"><span>나만의 주소</span>${icon('arrow')}<span>내 메일함</span></div></section><div class="section-heading"><h2>내가 만든 주소</h2><span class="small muted">예시 도메인 · 실제 수신 불가</span></div>${rows ? `<div class="email-table"><div class="table-labels"><span>이메일 주소</span><span>전달할 메일함</span><span class="label-state">전달 설정</span><span></span></div>${rows}<div class="table-footer"><span>총 ${state.aliases.length}개 주소</span><div class="page-numbers"><button class="selected" aria-current="page">1</button></div></div></div>` : empty('첫 번째 주소를 만들어 보세요','쇼핑, 뉴스레터, 업무용 주소를 따로 관리할 수 있어요.',button('주소 만들기','/emails/new'))}<a class="help-card" href="#/destinations"><span class="icon-tile">${icon('box')}</span><div><strong>메일을 받을 곳부터 연결할까요?</strong><p>본인 소유의 메일함을 인증하면 전달 설정에 사용할 수 있어요.</p></div>${icon('arrow')}</a>`));
  }
  function newEmail() { return shell(back()+heading('새 이메일 주소 만들기','용도에 맞는 이름으로, 나만의 주소를 만들어 보세요.')+`<div class="form-layout"><form class="panel form-main" data-form="alias"><div class="form-title"><span class="icon-tile mint">${icon('mail')}</span><h2>어떤 주소를 사용할까요?</h2></div><div class="field"><label for="alias">이메일 주소</label><div class="split-input"><input id="alias" name="alias" placeholder="my-new-address" required pattern="[a-z0-9][a-z0-9._-]{2,31}" maxlength="32" autocomplete="off"/><span class="at">@</span><select aria-label="도메인"><option>paperplane.example</option></select></div><p class="hint">영문 소문자, 숫자, 점, 밑줄, 하이픈 · 3~32자</p></div><div class="address-preview" id="alias-preview">my-new-address@paperplane.example</div>${formFoot('주소 만들기')}</form><aside class="form-note"><h3>이렇게 사용해 보세요</h3><p>shopping · 온라인 쇼핑<br/>newsletter · 읽고 싶은 소식<br/>studio · 함께하는 프로젝트</p><p>주소를 만든 다음, 전달할 메일함과 조건을 설정할 수 있어요.</p></aside></div>`,'주소 만들기',true); }
  function detail(id) { const a = aliasBy(id); if (!a) return notFound(); return shell(back()+heading(esc(address(a)),'이 주소로 오는 메일을 어디로 전달할지 정해 주세요.',`<button class="button secondary" data-action="copy" data-value="${address(a)}">${icon('copy')} 주소 복사</button>`)+`<div class="section-heading"><h2>전달 규칙 <span class="count">${a.rules.length}</span></h2>${button(`${icon('plus')} 전달 추가`,`/rule/${a.id}/new`,'secondary slim')}</div>${a.rules.length ? a.rules.map(r=>`<article class="rule-card"><div class="row between wrap"><div><div class="row">${icon('arrow')}<h3>${esc(r.destination)}</h3>${pill('설정 완료')}</div><p class="muted">${r.conditions.length ? esc(RuleDesigner.describe(RuleDesigner.normalize(r))) : '모든 메일을 전달해요'}</p></div><div class="row">${button('편집',`/rule/${a.id}/${r.id}`,'secondary slim')}<button class="icon-button" data-action="delete-rule" data-alias="${a.id}" data-id="${r.id}" aria-label="전달 규칙 삭제">${icon('trash')}</button></div></div></article>`).join('') : empty('아직 전달할 곳이 없어요','인증된 메일함을 연결하면 주소 설정이 완성돼요.',button('전달 추가',`/rule/${a.id}/new`))}<div class="note-line">${icon('box')} 이 시안에서는 실제 메일이 전송되지 않습니다.</div><div class="settings-row"><div><h3>이메일 주소 삭제</h3><p>전달 규칙과 이 주소의 전달 기록도 함께 삭제돼요.</p></div><button class="button danger-quiet" data-action="delete-alias" data-id="${a.id}">주소 삭제</button></div>`,'전달 설정'); }
  function destinations() { return shell(heading('받는 메일함','내 주소로 온 메일을 받아볼 실제 메일함이에요.',button(`${icon('plus')} 메일함 추가`,'/destinations/new'))+(specialState() || ((scenario === 'empty' ? [] : state.destinations).map(d=>`<div class="destination-row"><span class="icon-tile mint">${icon('box')}</span><div class="grow"><h3>${esc(d)}</h3><p class="muted small">내 메일함 · 소유 확인 완료</p></div>${pill('인증 완료')}<button class="icon-button" data-action="delete-destination" data-value="${esc(d)}" aria-label="${esc(d)} 삭제">${icon('trash')}</button></div>`).join('') || empty('메일을 받을 곳을 연결해 주세요','인증 코드를 확인한 메일함만 연결할 수 있어요.',button('메일함 추가','/destinations/new')))),'받는 메일함'); }
  function destinationNew() { return shell(back(returnToRule||'/destinations',returnToRule?'전달 규칙':'받는 메일함')+heading('받는 메일함 추가','메일함의 소유자를 확인한 후 연결해요.')+`<div class="form-layout"><form class="panel form-main" data-form="destination"><div class="steps"><b><span class="num">1</span> 이메일 입력</b><i></i><b><span class="num">2</span> 코드 확인</b></div>${codeSent ? `<div class="code-target"><strong>${esc(authEmail)}</strong><p>위 주소로 인증 코드를 보낸 상태를 보여드려요.</p></div>${field('6자리 인증 코드','code','123456','text','','required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" class="code-input"')}<p class="hint">데모 인증 코드: <strong>123456</strong> · 코드는 한 번만 사용할 수 있어요.</p><div class="row between"><span class="code-count" data-countdown></span><button type="button" class="text-button" data-action="resend">새 코드 받기</button></div>` : field('받는 이메일','email','hello@example.com','email','','required autocomplete="email"')} ${formFoot(codeSent ? '메일함 연결하기' : '인증 코드 받기',returnToRule||'/destinations')}</form><aside class="form-note"><h3>사용 중인 메일함을 입력해 주세요</h3><p>인증한 메일함은 여러 Paperplane 주소에서 함께 사용할 수 있어요.</p><p>이 화면은 인증 과정을 체험하는 시안입니다. 실제 인증 메일은 발송되지 않아요.</p></aside></div>`,'메일함 추가',true); }
  const fields = {subject:'제목',from:'보낸 주소',name:'보낸 사람',content:'본문',newsletter:'뉴스레터',date:'수신 날짜',attachment:'첨부 파일명'};

  function ruleEditor(aid,rid) {
    const a=aliasBy(aid); if(!a) return notFound();
    const key=`${aid}/${rid}`; if(!draft || draft.key!==key) { const r=a.rules.find(r=>r.id===Number(rid)); draft={key,destination:r?.destination || state.destinations[0] || '',conditions:structuredClone(r?.conditions || []),mode:r?.mode || 'all',conditional:!!r?.conditions.length,groups:RuleDesigner.normalize(r)}; dirty=false; }
    return shell(back(`/email/${aid}`,'전달 설정')+heading(rid==='new'?'전달 규칙 추가':'전달 규칙 편집',esc(address(a)))+`<div class="form-layout"><form class="panel form-main" data-form="rule" data-alias="${aid}" data-id="${rid}"><div class="field"><label for="destination">1. 어디로 전달할까요?</label><select id="destination" name="destination" required>${state.destinations.length ? state.destinations.map(d=>`<option ${draft.destination===d?'selected':''}>${esc(d)}</option>`).join('') : '<option value="">먼저 메일함을 인증해 주세요</option>'}</select><a class="text-button" href="#/destinations/new">새 메일함 연결하기 ↗</a></div><div class="field"><label>2. 어떤 메일을 전달할까요?</label><div class="radio-cards"><label class="radio-card"><input type="radio" name="kind" value="all" ${!draft.conditional?'checked':''}/><strong>모든 메일</strong><p>조건 없이 모두 전달해요</p></label><label class="radio-card"><input type="radio" name="kind" value="condition" ${draft.conditional?'checked':''}/><strong>조건에 맞는 메일</strong><p>내가 정한 메일만 골라요</p></label></div></div>${draft.conditional?`<div id="rule-groups">${RuleDesigner.render(draft.groups)}</div>`:''}<details class="test-panel"><summary>샘플 메일로 조건 테스트</summary><p class="hint">입력한 예시를 브라우저 안에서만 비교합니다.</p><div class="test-grid">${field('제목','test-subject','프로젝트 제안')}${field('보낸 주소','test-from','sender@example.com')}${field('보낸 사람','test-name','김민수')}${field('첨부 파일명','test-attachment','proposal.pdf')}${field('본문','test-content','함께 만들어요')}${field('수신 날짜','test-date','','date','2026-10-17')}<div class="field"><label for="test-newsletter">뉴스레터 여부</label><select id="test-newsletter"><option value="false">아니요</option><option value="true">예</option></select></div></div><button type="button" class="button secondary slim" data-action="test-rule">조건 테스트</button><div id="test-result" aria-live="polite"></div></details>${formFoot('규칙 저장',`/email/${aid}`)}</form><aside class="summary-card"><span class="eyebrow">전달 미리보기</span><h3>이렇게 전달돼요</h3><p id="rule-summary"></p><div class="note-line">${icon('plane')} 설정 동작을 보여주는 디자인 시안입니다.</div></aside></div>`,'전달 규칙',true);
  }
  function updateSummary(){
    if(!draft || !$('#rule-summary'))return;
    $('#rule-summary').textContent=`${draft.conditional ? RuleDesigner.describe(draft.groups) : '이 주소로 오는 모든 메일'}\n↓\n${draft.destination || '받는 메일함을 선택해 주세요'}`;
    const result=$('#test-result');
    if(result?.textContent)result.innerHTML='<p class="test-result stale">조건이 바뀌었어요. 다시 테스트해 주세요.</p>';
  }
  function refreshGroups(){
    const root=$('#rule-groups');if(root)root.innerHTML=RuleDesigner.render(draft.groups);
    updateSummary();
  }
  document.addEventListener('click',e=>{
    const button=e.target.closest('[data-rd-action]');if(!button||!draft)return;
    const groupIndex=Number(button.dataset.g)||0;
    RuleDesigner.action(draft.groups,button);dirty=true;refreshGroups();
    const root=$('#rule-groups');
    const groups=root.querySelectorAll('.rd-group');
    const group=groups[Math.min(groupIndex,groups.length-1)];
    if(button.dataset.rdAction==='group-add')groups[groups.length-1]?.querySelector('select')?.focus();
    else if(button.dataset.rdAction==='field-add')group?.querySelector('.rd-field:last-of-type select')?.focus();
    else if(button.dataset.rdAction==='term-add')group?.querySelectorAll('input')[group.querySelectorAll('input').length-1]?.focus();
    else (group?.querySelector('select')||root.querySelector('button'))?.focus();
  });
  document.addEventListener('input',e=>{
    if(!e.target.dataset.rdKey||!draft)return;
    const rerender=RuleDesigner.update(draft.groups,e.target);dirty=true;
    if(rerender){
      const {g,f}=e.target.dataset;refreshGroups();
      $(`[data-rd-key="field"][data-g="${g}"][data-f="${f}"]`)?.focus();
    }else updateSummary();
  });

  function deliveries(){ const records=[['10월 17일 09:42','shopping','hello@example.com','sent','전달 완료','250 OK · 예시 SMTP 응답'],['10월 17일 08:15','studio','work@example.com','retrying','재시도 기록','451 Temporary failure · 이후 상태는 별도 기록으로 확인'],['10월 16일 21:06','shopping','hello@example.com','failed','전달 실패','550 Mailbox unavailable · 예시 SMTP 응답']].filter(r=>state.aliases.some(a=>a.name===r[1])); return shell(heading('전달 기록','주소별 메일 처리 기록을 확인해 보세요.')+(specialState() || (scenario==='empty'||!records.length?empty('아직 전달 기록이 없어요','메일이 처리되면 기록이 이곳에 표시돼요.'):`<div class="alert info">아래 기록은 디자인 검토용 예시입니다. 재시도 기록은 최종 전달 결과를 뜻하지 않아요.</div><div class="email-table"><div class="delivery-header"><span>처리 시각</span><span>받은 주소</span><span>전달할 메일함</span><span>처리 결과</span></div>${records.map((r,i)=>`<div class="delivery-item"><button class="delivery-row" data-action="toggle-record" aria-expanded="false" aria-controls="record-${i}"><span class="small muted">${r[0]}</span><strong class="path-value">${r[1]}<span class="domain">@paperplane.example</span></strong><span class="path-value">${r[2]}</span>${pill(r[4],r[3]==='sent'?'':r[3]==='failed'?'red':'amber')}<span>⌄</span></button><div class="delivery-detail" id="record-${i}" hidden><dl><dt>처리 상세</dt><dd>${r[5]}</dd><dt>기록 ID</dt><dd>demo-event-${i+1}</dd><dt>메일 내용</dt><dd>전달 기록에는 본문이 표시되지 않습니다.</dd></dl></div></div>`).join('')}<div class="table-footer"><span>예시 기록 ${records.length}개</span><div class="page-numbers"><button class="selected">1</button></div></div></div>`)),'전달 기록'); }
  function settings(){return shell(heading('계정 설정','내 정보와 계정을 관리해요.')+`<form class="panel form-main" data-form="profile"><h2>프로필</h2>${field('이름','name','사용할 이름','text',state.name,'required maxlength="30"')}${field('이메일','account-email','','email','hello@example.com','disabled')}<p class="hint">이메일은 이 화면에서 변경할 수 없어요.</p>${formFoot('변경사항 저장','/settings')}</form><div class="settings-row"><div><h3>로그아웃</h3><p>이 브라우저의 계정에서 나갑니다.</p></div><button class="button secondary" data-action="logout">로그아웃</button></div><div class="settings-row"><div><h3>계정 삭제</h3><p>주소, 받는 메일함, 전달 규칙과 기록이 모두 삭제돼요.</p></div><button class="button danger-quiet" data-action="delete-account">계정 삭제</button></div>`,'계정 설정');}
  function auth(title,sub,body){return demoBar()+`<div class="auth-shell"><aside class="auth-story">${brand}<div class="auth-story-content"><span class="eyebrow">LESS NOISE. MORE YOU.</span><h1>주소는 여러 개.<br/>메일함은 하나.</h1><p>연결은 더 간편하게,<br/>내 메일 생활은 더 가볍게.</p><img class="paper-art" src="../public/logo.png" alt="종이비행기"/></div><div class="auth-story-footer">필요한 곳에, 필요한 메일만. — Paperplane</div></aside><main id="main" class="auth-main"><div class="auth-box"><div class="auth-mobile-brand">${brand}</div><h1>${title}</h1><p class="muted">${sub}</p>${body}<p class="auth-demo">디자인 체험용 화면입니다.<br/>실제 비밀번호나 개인정보를 입력하지 마세요.</p></div></main></div>`;}
  function login(){return auth('다시 만나서 반가워요','가벼운 메일 생활을 이어가세요.',`<div class="social-buttons"><a class="social-button" href="#/auth/callback"><span class="provider">G</span>Google로 계속하기</a><a class="social-button" href="#/auth/callback"><span class="provider naver">N</span>네이버로 계속하기</a></div><div class="divider"><span>또는 이메일로 로그인</span></div><form data-form="login">${field('이메일','email','hello@example.com','email','','required')}${field('비밀번호','password','데모용 문자 8자 이상','password','','required minlength="8"')}<p class="error" role="alert" data-error></p><button class="button wide">로그인 ${icon('arrow')}</button></form><div class="auth-links"><a href="#/password/reset">비밀번호를 잊으셨나요?</a></div><p class="auth-bottom">아직 계정이 없나요? <a href="#/signup">가입하기</a></p>`);}
  function signup(){return auth('나만의 주소로 시작하세요','메일을 받을 실제 이메일 주소를 알려주세요.',`<form data-form="signup">${field('이메일','email','hello@example.com','email',authEmail,'required')}<p class="hint">가입 확인 코드를 보내드려요. (이 시안에서는 발송하지 않아요.)</p><p class="error" role="alert" data-error></p><button class="button wide">인증 코드 받기 ${icon('arrow')}</button></form><p class="auth-bottom">이미 계정이 있나요? <a href="#/login">로그인</a></p>`);}
  function verify(){return auth('메일함을 확인해 주세요',`${esc(authEmail)}로 보낸 코드 입력 화면이에요.`,`<form data-form="verify">${field('6자리 인증 코드','code','123456','text','','required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" class="code-input"')}<div class="row between"><span class="code-count" data-countdown></span><button type="button" class="text-button" data-action="resend">새 코드 받기</button></div><p class="hint">데모 코드: 123456</p><p class="error" role="alert" data-error></p><button class="button wide">확인하고 계속하기</button></form><p class="auth-bottom"><a href="#/signup">다른 이메일로 가입하기</a></p>`);}
  function profileAuth(social=false){return auth('마지막으로, 이름을 알려주세요','Paperplane에서 사용할 정보를 입력해 주세요.',`<form data-form="signup-profile">${field('이름','name','어떻게 불러드릴까요?','text','','required maxlength="30"')}${social?'':field('비밀번호','password','8자 이상 입력해 주세요','password','','required minlength="8"')+field('비밀번호 확인','confirm','한 번 더 입력해 주세요','password','','required minlength="8"')}<p class="error" role="alert" data-error></p><button class="button wide">시작하기 ${icon('arrow')}</button></form>`);}
  function reset(newPassword=false){return auth(newPassword?'새 비밀번호를 정해 주세요':'비밀번호를 잊으셨나요?',newPassword?'새로운 비밀번호로 계정을 보호하세요.':'가입한 이메일로 복구 코드를 확인해요.',`<form data-form="${newPassword?'new-password':'reset'}">${newPassword?field('새 비밀번호','password','8자 이상','password','','required minlength="8"')+field('새 비밀번호 확인','confirm','다시 입력해 주세요','password','','required minlength="8"'):codeSent?field('인증 코드','code','123456','text','','required pattern="[0-9]{6}" inputmode="numeric"')+'<p class="hint">데모 코드: 123456</p>':field('가입 이메일','email','hello@example.com','email','','required')}<p class="error" role="alert" data-error></p><button class="button wide">${newPassword?'비밀번호 변경':codeSent?'코드 확인':'복구 코드 받기'}</button></form><p class="auth-bottom"><a href="#/login">로그인으로 돌아가기</a></p>`);}
  function landing(){return demoBar()+`<header class="public-nav">${brand}<div class="row">${button('로그인','/login','ghost')}${button('시작하기','/signup','slim')}</div></header><main id="main" class="landing"><section class="hero"><div><span class="eyebrow">YOUR INBOX, SIMPLIFIED</span><h1>메일 주소는 자유롭게.<br/><em>메일함은 가볍게.</em></h1><p>쇼핑할 때도, 새로운 소식을 구독할 때도.<br/>나만의 주소를 만들고 익숙한 메일함으로 받아보세요.</p><div class="row wrap">${button('나만의 주소 만들기 '+icon('arrow'),'/signup')}${button('데모 둘러보기','/emails','secondary')}</div><p class="small muted">내 메일함은 그대로, 주소만 더 자유롭게.</p></div><div class="hero-visual"><img src="../public/logo.png" alt="민트색 종이비행기"/><div class="mail-preview"><span class="icon-tile mint">${icon('mail')}</span><div><strong>shopping@paperplane.example</strong><p>쇼핑할 때 쓰는 나만의 주소</p></div></div><div class="visual-connector">↓</div><div class="mail-preview"><span class="icon-tile">${icon('box')}</span><div><strong>hello@example.com</strong><p>늘 사용하던 내 메일함</p></div>${pill('연결')}</div></div></section><section class="landing-steps">${[['01','주소를 만들고','용도에 맞게 나만의 이메일 주소를 만들어요.'],['02','받을 곳을 연결하고','본인 소유의 메일함을 인증해 연결해요.'],['03','필요한 메일만 받아요','모두 전달하거나, 원하는 조건을 직접 정해요.']].map(([n,t,p])=>`<article><span class="eyebrow">${n}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</section><section class="landing-example"><span class="eyebrow">A LITTLE MORE ORGANIZED</span><h2>각자의 용도에 맞는 주소.<br/>한곳에서 이어지는 메일.</h2><p>복잡한 새 메일함 대신, 간단한 전달 설정으로 시작하세요.</p>${button('직접 체험하기','/emails','secondary')}</section></main><footer class="landing-footer">${brand}<span>Paperplane 디자인 프로토타입 · 실제 메일 전달 없음</span></footer>`;}
  function success(){return shell(`<div class="success-panel"><span class="success-mark">${icon('check')}</span><span class="eyebrow">READY TO GO</span><h1>나만의 이메일 준비 완료!</h1><p>이제 주소별로 원하는 메일함과 전달 조건을 설정할 수 있어요.</p><div class="success-route"><strong>${esc(state.aliases[0]?address(state.aliases[0]):'첫 주소를 만들어 주세요')}</strong>${icon('arrow')}<strong>${esc(state.destinations[0]||'받는 메일함 연결')}</strong></div><p class="muted small">시안의 완료 화면입니다. 실제 전달은 수행되지 않습니다.</p>${button('내 이메일로 이동','/emails')}</div>`);}
  function notFound(){return shell(heading('페이지를 찾을 수 없어요','요청한 주소를 다시 확인해 주세요.')+empty('404','주소가 바뀌었거나 삭제되었을 수 있어요.',button('내 이메일로 돌아가기','/emails')));}
  function render(){route=location.hash.slice(1).split('?')[0]||'/emails'; let html; const parts=route.split('/');
    if(route==='/') html=landing(); else if(route==='/emails')html=emails(); else if(route==='/emails/new')html=newEmail(); else if(parts[1]==='email')html=detail(parts[2]); else if(parts[1]==='rule')html=ruleEditor(parts[2],parts[3]); else if(route==='/destinations')html=destinations(); else if(route==='/destinations/new')html=destinationNew(); else if(route==='/deliveries')html=deliveries(); else if(route==='/settings')html=settings(); else if(route==='/login')html=login(); else if(route==='/signup')html=signup(); else if(route==='/signup/verify')html=verify(); else if(route==='/signup/profile'||route==='/signup/social')html=profileAuth(route.endsWith('social')); else if(route==='/password/reset'||route==='/password/reset/new')html=reset(route.endsWith('new')); else if(route==='/auth/callback')html=auth('소셜 인증을 마쳤어요','외부 인증 화면은 이 시안에서 생략합니다.',`<div class="alert info">실제 Google·네이버 계정에 연결하지 않는 예시 화면이에요.</div>${button('기존 계정으로 계속','/emails','wide')}<br/>${button('신규 가입 이어가기','/signup/social','secondary wide')}`); else if(route==='/success')html=success(); else if(route==='/session')html=auth('다시 로그인해 주세요','안전한 이용을 위해 로그인이 필요해요.',button('로그인으로 이동','/login','wide')); else html=notFound();
    app.innerHTML=html; document.title=`${$('#main h1')?.textContent || 'Paperplane'} — Paperplane`; updateSummary(); updateTimer();
  }
  function gallery(){modal('화면 둘러보기',`<p class="muted">화면을 선택하거나 데이터 상태를 바꿔보세요. 데이터는 새로고침하면 초기화됩니다.</p><div class="gallery-controls"><label>목록 상태<select id="scenario"><option value="normal">기본 데이터</option><option value="empty">빈 목록</option><option value="loading">불러오는 중</option><option value="error">연결 오류</option></select></label><label><input type="checkbox" id="fail-next" ${failNext?'checked':''}/> 다음 저장 요청 실패</label></div><div class="gallery-grid">${screens.map(([label,path],i)=>`<a class="gallery-link" href="#${path}" data-action="gallery-go"><small>P${String(i+1).padStart(2,'0')}</small>${label}${icon('arrow')}</a>`).join('')}</div><p class="small muted">빈 목록·로딩·오류는 내 이메일 / 받는 메일함 / 전달 기록에 적용돼요.</p>`,`<button class="button secondary" data-action="reset-demo">예시 데이터 초기화</button><button class="button" data-action="close">닫기</button>`);dialog.className='gallery';$('#scenario').value=scenario;}
  function confirmDelete(title,text,callback){modal(title,`<p>${text}</p><p class="small muted">이 동작은 현재 미리보기의 예시 데이터에만 적용됩니다.</p>`,`<button class="button secondary" data-action="close">취소</button><button class="button danger" id="confirm-delete">삭제하기</button>`);$('#confirm-delete').onclick=()=>{callback();dialog.close();dirty=false;render();toast('삭제했어요.');};}
  function updateTimer(){const node=$('[data-countdown]');if(node){const duration=route==='/destinations/new'?600:1800;const remain=Math.max(0,duration-Math.floor((Date.now()-timerStart)/1000));node.textContent=timerStart?`남은 시간 ${Math.floor(remain/60)}:${String(remain%60).padStart(2,'0')}`:`유효 시간 ${duration/60}:00`;}}
  setInterval(updateTimer,1000);
  document.addEventListener('input',e=>{if(e.target.id.startsWith('test-')){const result=$('#test-result');if(result?.textContent)result.innerHTML='<p class="test-result stale">샘플이 바뀌었어요. 다시 테스트해 주세요.</p>';}});
  document.addEventListener('click',async e=>{
    if(e.target.closest('.skip-link')){e.preventDefault();const main=$('#main');main.tabIndex=-1;main.focus();return;}
    const b=e.target.closest('[data-action]'); if(!b)return; const action=b.dataset.action;
    if(action==='toggle-password'){
      const input=document.getElementById(b.dataset.target),show=input.type==='password';
      input.type=show?'text':'password';b.textContent=show?'숨기기':'보기';b.setAttribute('aria-pressed',String(show));
      b.setAttribute('aria-label',`${input.name==='confirm'?'비밀번호 확인':'비밀번호'} ${show?'숨기기':'표시'}`);return;
    }
    if(action==='close')dialog.close(); else if(action==='gallery')gallery(); else if(action==='gallery-go'){dialog.close();dirty=false;codeSent=false;scenario=$('#scenario').value;if(b.hash===location.hash)render();} else if(action==='retry'){scenario='normal';render();} else if(action==='reset-demo'){state=initial();draft=null;dirty=false;scenario='normal';failNext=false;dialog.close();location.hash='/emails';render();toast('예시 데이터를 초기화했어요.');}
    else if(action==='copy'){try{await navigator.clipboard.writeText(b.dataset.value);toast('이메일 주소를 복사했어요.');}catch{modal('주소 복사',`<input readonly aria-label="복사할 주소" value="${esc(b.dataset.value)}"/>`);$('input',dialog).select();}}
    else if(action==='delete-alias')confirmDelete('이 주소를 삭제할까요?','연결된 전달 규칙과 기록이 함께 삭제돼요.',()=>{state.aliases=state.aliases.filter(a=>a.id!==Number(b.dataset.id));location.hash='/emails';});
    else if(action==='delete-rule')confirmDelete('전달 규칙을 삭제할까요?','이 규칙에 따른 전달 설정이 사라져요.',()=>{const a=aliasBy(b.dataset.alias);a.rules=a.rules.filter(r=>r.id!==Number(b.dataset.id));});
    else if(action==='delete-destination'){const target=b.dataset.value;const count=state.aliases.flatMap(a=>a.rules).filter(r=>r.destination===target).length;confirmDelete('받는 메일함을 삭제할까요?',`${esc(target)}에 연결된 규칙 ${count}개도 함께 삭제돼요.`,()=>{state.destinations=state.destinations.filter(d=>d!==target);state.aliases.forEach(a=>a.rules=a.rules.filter(r=>r.destination!==target));});}
    else if(action==='delete-account')confirmDelete('계정을 삭제할까요?','모든 주소, 받는 메일함, 규칙과 기록이 삭제돼요.',()=>{state={name:'게스트',aliases:[],destinations:[]};location.hash='/signup';});
    else if(action==='logout'){location.hash='/login';toast('데모 계정에서 로그아웃했어요.');}
    else if(action==='toggle-record'){const expanded=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!expanded));document.getElementById(b.getAttribute('aria-controls')).hidden=expanded;}
    else if(action==='resend'){const cooldown=route==='/destinations/new'?60:30;const elapsed=(Date.now()-timerStart)/1000;if(timerStart && elapsed<cooldown){toast(`${Math.ceil(cooldown-elapsed)}초 후 다시 받을 수 있어요.`);return;}timerStart=Date.now();verifyAttempts=0;toast('새 코드를 준비했어요. 데모 코드: 123456');updateTimer();}
    else if(action==='test-rule'){
      const error=draft.conditional?RuleDesigner.validate(draft.groups):'';
      if(error){$('#test-result').innerHTML=`<p class="test-result no">${esc(error)}</p>`;return;}
      const sample=Object.fromEntries(Object.keys(RuleDesigner.labels).map(key=>[key,$(`#test-${key}`)?.value || '']));
      const pass=!draft.conditional||RuleDesigner.matches(draft.groups,sample);
      $('#test-result').innerHTML=`<p class="test-result ${pass?'':'no'}">${pass?'✓ 이 샘플은 전달 조건에 맞아요.':'이 샘플은 전달 조건에 맞지 않아요.'}</p>`;
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='alias')$('#alias-preview').textContent=`${e.target.value||'my-new-address'}@paperplane.example`;if(e.target.closest('form[data-form="rule"]')&&!e.target.id.startsWith('test-'))dirty=true;});
  document.addEventListener('change',e=>{if(e.target.id==='scenario'){scenario=e.target.value;render();}if(e.target.id==='fail-next')failNext=e.target.checked;if(e.target.name==='kind'){draft.conditional=e.target.value==='condition';if(draft.conditional&&!draft.groups.length)draft.groups=RuleDesigner.normalize();dirty=true;render();}if(e.target.id==='destination'){draft.destination=e.target.value;dirty=true;updateSummary();}if(e.target.id==='match-mode'){draft.mode=e.target.value;dirty=true;updateSummary();}});
  document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));const error=$('[data-error]',form);error.textContent='';const kind=form.dataset.form;const submit=$('button[type="submit"],button:not([type])',form);const original=submit.innerHTML;submit.disabled=true;submit.textContent='처리 중…';await new Promise(r=>setTimeout(r,500));submit.disabled=false;submit.innerHTML=original;if(!form.isConnected)return;if(failNext){failNext=false;error.textContent='연결하지 못했어요. 입력한 내용은 유지됩니다. 다시 시도해 주세요.';return;}const fail=message=>{error.textContent=message;error.tabIndex=-1;error.focus();};
    if(data.name&&(data.name.trim().length<2||data.name.trim().length>8))return fail('이름은 2~8자로 입력해 주세요.');
    if(data.password&&!hasSpecial(data.password))return fail('비밀번호에 특수문자를 하나 이상 포함해 주세요.');
    if(kind==='alias'){if(state.aliases.some(a=>a.name===data.alias))return fail('이미 사용 중인 주소예요. 다른 이름을 입력해 주세요.');const a={id:nextId++,name:data.alias,rules:[]};state.aliases.unshift(a);location.hash=`/email/${a.id}`;toast('주소를 만들었어요. 전달할 곳을 연결해 주세요.');}
    else if(kind==='destination'){if(!codeSent){if(state.destinations.includes(data.email))return fail('이미 연결된 메일함이에요.');authEmail=data.email;codeSent=true;timerStart=Date.now();render();}else{if(Date.now()-timerStart>600000)return fail('코드가 만료됐어요. 새 코드를 받아 주세요.');if(data.code!=='123456'){codeSent=false;render();toast('코드가 일치하지 않아요. 인증을 새로 시작해 주세요.');return;}state.destinations.push(authEmail);codeSent=false;const target=returnToRule||'/destinations';if(returnToRule&&draft)draft.destination=authEmail;returnToRule='';location.hash=target;toast('메일함을 연결했어요.');}}
    else if(kind==='rule'){
      const invalid=draft.conditional?RuleDesigner.validate(draft.groups):'';
      if(invalid)return fail(invalid);
      const a=aliasBy(form.dataset.alias), id=form.dataset.id==='new'?nextId++:Number(form.dataset.id);
      const groups=draft.conditional?structuredClone(draft.groups):[];
      const rule={id,destination:data.destination,conditions:RuleDesigner.flatten(groups),groups};
      const index=a.rules.findIndex(r=>r.id===id);if(index<0)a.rules.push(rule);else a.rules[index]=rule;
      draft=null;dirty=false;location.hash=`/email/${a.id}`;toast('전달 규칙을 저장했어요.');
    }
    else if(kind==='profile'){state.name=data.name.trim()||'지민';render();toast('이름을 변경했어요.');}
    else if(kind==='login')location.hash='/emails';
    else if(kind==='signup'){authEmail=data.email;timerStart=Date.now();verifyAttempts=0;location.hash='/signup/verify';}
    else if(kind==='verify'){
      if(verifyAttempts>=5)return fail('확인 횟수를 초과했어요. 새 코드를 받아 주세요.');
      if(timerStart&&Date.now()-timerStart>1800000)return fail('코드가 만료됐어요. 새 코드를 받아 주세요.');
      if(data.code!=='123456'){verifyAttempts++;return fail(verifyAttempts>=5?'확인 횟수를 초과했어요. 새 코드를 받아 주세요.':`인증 코드가 일치하지 않아요. ${5-verifyAttempts}번 더 확인할 수 있어요.`);}
      location.hash='/signup/profile';
    }
    else if(kind==='signup-profile'){if(data.password?.trim()!==data.confirm?.trim())return fail('비밀번호가 서로 달라요.');state.name=data.name;state.aliases=[];state.destinations=[];scenario='normal';location.hash='/emails';toast('가입을 완료했어요. 첫 주소를 만들어 보세요.');}
    else if(kind==='reset'){if(!codeSent){codeSent=true;authEmail=data.email;render();}else{if(data.code!=='123456')return fail('인증 코드가 일치하지 않아요.');codeSent=false;location.hash='/password/reset/new';}}
    else if(kind==='new-password'){if(data.password?.trim()!==data.confirm?.trim())return fail('비밀번호가 서로 달라요.');location.hash='/login';toast('비밀번호 변경 완료 화면을 체험했어요.');}
  });
  // Keep unfinished rule edits available when navigating to destination verification.
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);const main=$('#main');if(main){main.tabIndex=-1;main.focus({preventScroll:true});}});
  render();
})();
